def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def first_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def pos(key, default=(0, 0)):
        v = observation.get(key, default)
        p = first_pair(v)
        return p if p is not None else default

    def grid_size():
        w = observation.get("grid_width", observation.get("width", 0))
        h = observation.get("grid_height", observation.get("height", 0))
        try:
            w = int(w)
        except Exception:
            w = 0
        try:
            h = int(h)
        except Exception:
            h = 0
        return w, h

    def step_toward(a, b):
        ax, ay = a
        bx, by = b
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_points(name):
        v = observation.get(name, [])
        if not isinstance(v, (list, tuple)):
            return []
        out = []
        for item in v:
            p = first_pair(item)
            if p is not None:
                out.append((p[0], p[1]))
        return out

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos("self_position")
    ox, oy = pos("opponent_position", (sx, sy))
    me = (sx, sy)
    opp = (ox, oy)
    w, h = grid_size()

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(me, opp)
        corners = []
        if w > 0 and h > 0:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = corners[0]
        best = -1
        for c in corners:
            d = manhattan(c, opp)
            if d > best:
                best = d
                target = c
        return step_toward(me, target)

    if env == "territory_control":
        targets = safe_points("unclaimed_cells")
        if not targets:
            targets = safe_points("opponent_territory")
        if targets:
            best = targets[0]
            best_d = manhattan(me, best)
            for t in targets[1:]:
                d = manhattan(me, t)
                if d < best_d:
                    best_d = d
                    best = t
            return step_toward(me, best)
        if w > 0 and h > 0:
            center = (w // 2, h // 2)
            return step_toward(me, center)
        return [0, 0]

    resources = safe_points("resources")
    if resources:
        best = resources[0]
        best_d = manhattan(me, best)
        for r in resources[1:]:
            d = manhattan(me, r)
            if d < best_d:
                best_d = d
                best = r
        return step_toward(me, best)

